STALL_THRESHOLD_MS = 30_000


def count_stalls(events):
    """统计 stall 事件数(duration >= 阈值的 resolver_try / download_one / fetch_video_info)。"""
    stalls = 0
    for ev in events:
        if ev.step == "resolver_try":
            pass
        if ev.step in ("resolver_try", "download_one", "fetch_video_info"):
            if ev.duration_ms >= STALL_THRESHOLD_MS:
                stalls += 1
    return stalls

